import{useEffect,useMemo,useRef,useState}from'react';import{Link,useParams}from'react-router-dom';import api from'../services/api';import{useAuth}from'../context/AuthContext';import{Search,CheckCircle2,AlertCircle,Send,Plus,RefreshCw,ArrowLeft,FileText,X}from'lucide-react';
function Header({tag,title,desc}){return <div className="welcome-row"><div><span className="eyebrow">{tag}</span><h1>{title}</h1><p className="muted">{desc}</p></div></div>}
async function downloadDocumentFile(documentRecord){const blob=await api.get(`/documents/${documentRecord._id}/file`,{responseType:'blob'});const url=window.URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=documentRecord.originalName||documentRecord.fileName||'admission-document';document.body.appendChild(link);link.click();link.remove();window.setTimeout(()=>window.URL.revokeObjectURL(url),60000);}
const numberOrNull=value=>value===''?null:Number(value);
export function Profile(){const{user}=useAuth();const[profile,setProfile]=useState(null),[form,setForm]=useState({fullName:'',phone:'',dateOfBirth:'',gender:'Other',state:'',city:'',category:'OPEN',subcategory:'',examName:'JEE Main',rank:'',score:'',percentile:'',interestedBranches:'',academicInfo:{board:'',schoolName:'',stream:'',class10Percentage:'',class12Percentage:''}}),[saving,setSaving]=useState(false),[message,setMessage]=useState(''),[error,setError]=useState('');
 const load=async()=>{try{const r=await api.get('/students/me');const data=r.data||r;const student=data.data||data;setProfile(student);setForm({fullName:student.fullName||student.user?.name||'',phone:student.phone||student.user?.phone||'',dateOfBirth:student.dateOfBirth?new Date(student.dateOfBirth).toISOString().slice(0,10):'',gender:student.gender||'Other',state:student.state||'',city:student.city||'',category:student.category||'OPEN',subcategory:student.subcategory||'',examName:student.examName||'JEE Main',rank:student.rank ?? '',score:student.score ?? '',percentile:student.percentile ?? '',interestedBranches:Array.isArray(student.interestedBranches)?student.interestedBranches.join(', '):'',academicInfo:{board:student.academicInfo?.board||'',schoolName:student.academicInfo?.schoolName||'',stream:student.academicInfo?.stream||'',class10Percentage:student.academicInfo?.class10Percentage ?? '',class12Percentage:student.academicInfo?.class12Percentage ?? ''}});}catch(e){setError(e.message||'Unable to load profile.');}};
 useEffect(()=>{if(user?.role==='student')load();},[user?.role]);
 const updateField=(field,value)=>setForm(prev=>({...prev,[field]:value}));
 const updateAcademic=(field,value)=>setForm(prev=>({...prev,academicInfo:{...prev.academicInfo,[field]:value}}));
 const submit=async e=>{e.preventDefault();setSaving(true);setError('');setMessage('');try{const payload={...form,dateOfBirth:form.dateOfBirth||null,rank:numberOrNull(form.rank),score:numberOrNull(form.score),percentile:numberOrNull(form.percentile),phone:form.phone,interestedBranches:form.interestedBranches.split(',').map(v=>v.trim()).filter(Boolean),academicInfo:{...form.academicInfo,class10Percentage:numberOrNull(form.academicInfo.class10Percentage),class12Percentage:numberOrNull(form.academicInfo.class12Percentage)}};const r=await api.patch('/students/me',payload);const student=r.data||r;setProfile(student.data||student);setMessage('Profile saved successfully.');}catch(e){setError(e.message||'Unable to save profile.');}finally{setSaving(false);}};
 const completion=Number(profile?.profileCompletion || 0);
 if(user?.role==='admin')return <><Header tag="ADMINISTRATOR PROFILE" title={user.name||'Administrator'} desc="Your signed-in administrator account and workspace access."/><section className="panel administrator-profile-card"><div className="avatar">{user.name?.[0]?.toUpperCase()||'A'}</div><div><h2>{user.name||'Administrator'}</h2><p>{user.email||'No email address'}</p><span className="badge approved">Administrator access</span></div></section></>;
 return <><Header tag="STUDENT PROFILE" title="Complete your academic profile" desc="Keep your details up to date so administrators can verify eligibility and counselling readiness."/>
 <div className="panel"><div className="welcome-row"><div><span className="eyebrow">PROFILE COMPLETION</span><h2 style={{margin:'10px 0 6px'}}>{completion}% complete</h2></div><div style={{minWidth:'220px',width:'260px',background:'#edf2fb',height:'10px',borderRadius:'999px',overflow:'hidden'}}><div style={{width:`${completion}%`,height:'100%',background:'linear-gradient(90deg,#315fe0,#6e8dff)'}}/></div></div></div>
 <form className="form-grid" onSubmit={submit}>
  <label>Full name<input value={form.fullName} onChange={e=>updateField('fullName',e.target.value)} placeholder="Student full name" /></label>
  <label>Email<input value={profile?.user?.email || ''} readOnly disabled /></label>
  <label>Phone number<input type="tel" inputMode="tel" maxLength="13" pattern="(\+91)?[6-9][0-9]{9}" value={form.phone} onChange={e=>updateField('phone',e.target.value)} placeholder="9876543210 or +919876543210" /></label>
  <label>Date of birth<input type="date" value={form.dateOfBirth} onChange={e=>updateField('dateOfBirth',e.target.value)} /></label>
  <label>Gender<select value={form.gender} onChange={e=>updateField('gender',e.target.value)}><option value="Male">Male</option><option value="Female">Female</option><option value="Other">Other</option></select></label>
  <label>State<input value={form.state} onChange={e=>updateField('state',e.target.value)} placeholder="State" /></label>
  <label>City<input value={form.city} onChange={e=>updateField('city',e.target.value)} placeholder="City" /></label>
  <label>Category<select value={form.category} onChange={e=>updateField('category',e.target.value)}>{['OPEN','EWS','OBC-NCL','SC','ST'].map(v=><option key={v} value={v}>{v}</option>)}</select></label>
  <label>Subcategory<input value={form.subcategory} onChange={e=>updateField('subcategory',e.target.value)} placeholder="If any" /></label>
  <label>Entrance exam<select value={form.examName} onChange={e=>updateField('examName',e.target.value)}><option value="JEE Main">JEE Main</option><option value="JEE Advanced">JEE Advanced</option><option value="CUET">CUET</option><option value="MHT CET">MHT CET</option></select></label>
  <label>Rank<input type="number" min="1" value={form.rank} onChange={e=>updateField('rank',e.target.value)} placeholder="e.g. 8500" /></label>
  <label>Score<input type="number" min="0" value={form.score} onChange={e=>updateField('score',e.target.value)} placeholder="Score / marks" /></label>
  <label>Percentile<input type="number" min="0" max="100" step="0.1" value={form.percentile} onChange={e=>updateField('percentile',e.target.value)} placeholder="e.g. 96.5" /></label>
  <label>Interested branches<input value={form.interestedBranches} onChange={e=>updateField('interestedBranches',e.target.value)} placeholder="CSE, ECE, Mechanical" /></label>
  <label>Board<input value={form.academicInfo.board} onChange={e=>updateAcademic('board',e.target.value)} placeholder="CBSE / ICSE / State Board" /></label>
  <label>School name<input value={form.academicInfo.schoolName} onChange={e=>updateAcademic('schoolName',e.target.value)} placeholder="School name" /></label>
  <label>Stream<select value={form.academicInfo.stream} onChange={e=>updateAcademic('stream',e.target.value)}><option value="">Select</option><option value="Science">Science</option><option value="Commerce">Commerce</option><option value="Arts">Arts</option></select></label>
  <label>Class 10 %<input type="number" min="0" max="100" step="0.1" value={form.academicInfo.class10Percentage} onChange={e=>updateAcademic('class10Percentage',e.target.value)} /></label>
  <label>Class 12 %<input type="number" min="0" max="100" step="0.1" value={form.academicInfo.class12Percentage} onChange={e=>updateAcademic('class12Percentage',e.target.value)} /></label>
  <div className="form-action" style={{gridColumn:'1 / -1'}}><button className="btn primary" disabled={saving}>{saving?'Saving…':'Save profile'}</button></div>
 </form>
 {message&&<div className="alert success">{message}</div>}
 {error&&<div className="alert error">{error}</div>}
 </>} 
export function Predictor(){const[form,setForm]=useState({rank:'',category:'OPEN',examName:'JEE Main'}),[data,setData]=useState([]),[meta,setMeta]=useState(null),[error,setError]=useState('');const run=async e=>{e.preventDefault();setError('');try{const r=await api.post('/predictor',form);setData(r.data);setMeta(r.meta);}catch(x){setError(x.message);}};return <><Header tag="PREDICTIVE SIMULATION ENGINE" title="Rank predictor" desc="Explore possible college and branch matches using historical cutoff records."/><div className="panel"><form className="form-grid" onSubmit={run}><label>Entrance exam<select value={form.examName} onChange={e=>setForm({...form,examName:e.target.value})}><option>JEE Main</option></select></label><label>All India rank<input type="number" min="1" required value={form.rank} onChange={e=>setForm({...form,rank:e.target.value})} placeholder="e.g. 8500"/></label><label>Category<select value={form.category} onChange={e=>setForm({...form,category:e.target.value})}>{['OPEN','EWS','OBC-NCL','SC','ST'].map(x=><option key={x}>{x}</option>)}</select></label><div className="form-action"><button className="btn primary"><Search size={16}/> Analyse my rank</button></div></form>{error&&<div className="alert error">{error}</div>}</div>{meta&&<><div className="result-note">Found {meta.recordsFound} matches against {meta.cutoffYear} cutoff data. {meta.notice}</div><div className="table-wrap"><table><thead><tr><th>College</th><th>Branch</th><th>Closing rank</th><th>Chance indicator</th><th>Cutoff fit score</th></tr></thead><tbody>{data.map((x,i)=><tr key={i}><td><b>{x.college}</b><small className="table-sub">{x.location}</small></td><td>{x.branch}</td><td>{x.closingRank.toLocaleString()}</td><td><span className={`badge ${x.chance.toLowerCase()}`}>{x.chance}</span></td><td>{x.matchScore}%</td></tr>)}</tbody></table>{!data.length&&<div className="empty">No cutoff records found for these filters. Ask an administrator to add data.</div>}</div></>}</>}
export function Colleges(){
 const[data,setData]=useState([]),[q,setQ]=useState(''),[err,setErr]=useState(''),[selectedCollege,setSelectedCollege]=useState(null);
 const load=async()=>{try{const response=await api.get('/colleges',{params:{search:q}});setData(Array.isArray(response.data)?response.data:[]);setErr('');}catch(error){setErr(error.message||'Unable to load colleges.');}};
 useEffect(()=>{load();},[]);
 useEffect(()=>{if(!selectedCollege)return;const closeOnEscape=event=>{if(event.key==='Escape')setSelectedCollege(null);};window.addEventListener('keydown',closeOnEscape);return()=>window.removeEventListener('keydown',closeOnEscape);},[selectedCollege]);
 const openCollege=(college)=>setSelectedCollege(college);
 const formatMoney=value=>Number.isFinite(Number(value))?`₹${Number(value).toLocaleString('en-IN')}`:'Not provided';
 return <><Header tag="COLLEGE DIRECTORY" title="Explore colleges" desc="Select an institution to inspect its programmes, seat availability, fees and historical cutoffs."/><div className="searchbar"><Search/><input placeholder="Search colleges by name…" value={q} onChange={event=>setQ(event.target.value)} onKeyDown={event=>{if(event.key==='Enter')load();}}/><button className="btn secondary" type="button" onClick={load}>Search</button></div>{err&&<div className="alert error">{err}</div>}<div className="college-grid">{data.map(college=><article className="college-card" key={college._id} role="button" tabIndex={0} aria-haspopup="dialog" onClick={()=>openCollege(college)} onKeyDown={event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();openCollege(college);}}}><div className="college-mark">{college.code?.slice(0,2)}</div><span className="badge neutral">{college.type}</span><h3>{college.name}</h3><p>{college.location}</p><div className="branch-list">{college.branches?.slice(0,3).map(branch=><div key={branch._id}><span>{branch.name}</span><small>{branch.totalSeats} seats · {formatMoney(branch.fees)}</small></div>)}</div><span className="college-card-action">View college details</span></article>)}</div>{!data.length&&!err&&<div className="empty">No colleges available yet.</div>}{selectedCollege&&<div className="college-modal-backdrop" onMouseDown={event=>{if(event.target===event.currentTarget)setSelectedCollege(null);}}><section className="college-modal" role="dialog" aria-modal="true" aria-labelledby="college-modal-title"><header className="college-modal-header"><div><span className="eyebrow">COLLEGE DETAILS · {selectedCollege.code}</span><h2 id="college-modal-title">{selectedCollege.name}</h2><p>{selectedCollege.location} · {selectedCollege.type}</p></div><button className="btn secondary" type="button" aria-label="Close college details" onClick={()=>setSelectedCollege(null)}>Close</button></header>{selectedCollege.description&&<p className="college-description">{selectedCollege.description}</p>}{selectedCollege.website&&<a className="college-website" href={selectedCollege.website} target="_blank" rel="noreferrer">Visit official website</a>}<h3>Branches and programmes</h3>{selectedCollege.branches?.length?<div className="college-modal-branches">{selectedCollege.branches.map(branch=><article className="college-branch-detail" key={branch._id}><div className="college-branch-heading"><div><h4>{branch.name}</h4><small>Branch code: {branch.code}</small></div><span className={`badge ${branch.isActive?'approved':'neutral'}`}>{branch.isActive?'Active':'Inactive'}</span></div><div className="college-branch-stats"><div><span>Total seats</span><b>{branch.totalSeats??'Not provided'}</b></div><div><span>Seats available</span><b>{Math.max(0,Number(branch.totalSeats||0)-Number(branch.allocatedSeats||0))}</b></div><div><span>Fees</span><b>{formatMoney(branch.fees)}</b></div></div><h5>Historical cutoffs</h5>{branch.cutoffs?.length?<div className="table-wrap college-cutoff-table"><table><thead><tr><th>Year</th><th>Round</th><th>Exam</th><th>Category</th><th>Opening</th><th>Closing</th></tr></thead><tbody>{branch.cutoffs.map(cutoff=><tr key={cutoff._id}><td>{cutoff.year}</td><td>{cutoff.round}</td><td>{cutoff.examName}</td><td>{cutoff.category}</td><td>{cutoff.openingRank??'—'}</td><td>{cutoff.closingRank}</td></tr>)}</tbody></table></div>:<p className="muted">No cutoff data has been imported for this branch.</p>}</article>)}</div>:<div className="empty">No active branches are listed for this college.</div>}</section></div>}</>;
}
export function Preferences(){
 const[rounds,setRounds]=useState([]),[round,setRound]=useState(''),[colleges,setColleges]=useState([]),[preferences,setPreferences]=useState([]),[choices,setChoices]=useState([]),[selectedBranch,setSelectedBranch]=useState(''),[locked,setLocked]=useState(false),[saved,setSaved]=useState(''),[err,setErr]=useState('');
 const all=useMemo(()=>colleges.flatMap(college=>(college.branches||[]).map(branch=>({id:branch._id,label:`${college.name} — ${branch.name}`}))),[colleges]);
 const refreshRounds=async()=>{try{const response=await api.get('/rounds');const availableRounds=response.data||[];setRounds(availableRounds);if(round&&!availableRounds.some(item=>String(item._id)===String(round))){setRound('');setSaved('');}else if(!round){const activeRound=availableRounds.find(item=>item.status==='open');if(activeRound)setRound(activeRound._id);}setErr('');}catch(e){setErr(e.message||'Unable to refresh admission rounds.');}};
 useEffect(()=>{const load=async()=>{try{const [collegeRes,roundRes,preferenceRes]=await Promise.all([api.get('/colleges'),api.get('/rounds'),api.get('/preferences/mine')]);const roundData=roundRes.data||[];setColleges(collegeRes.data||[]);setRounds(roundData);setPreferences(preferenceRes.data||[]);const activeRound=roundData.find(r=>r.status==='open')||roundData[0];if(activeRound)setRound(activeRound._id);}catch(e){setErr(e.message||'Unable to load preferences.');}};load();},[]);
 useEffect(()=>{let mounted=true;const timer=window.setInterval(async()=>{try{const response=await api.get('/rounds');if(mounted){const availableRounds=response.data||[];setRounds(availableRounds);setRound(current=>current&&!availableRounds.some(item=>String(item._id)===String(current))?'':current);}}catch(e){if(mounted)setErr(e.message||'Unable to refresh admission rounds.');}},15000);return()=>{mounted=false;window.clearInterval(timer);};},[]);
 useEffect(()=>{const preference=preferences.find(item=>String(item.admissionRound?._id||item.admissionRound)===String(round));setChoices(preference?.choices.map(choice=>{const branch=choice.branch?._id||choice.branch;const catalogBranch=all.find(item=>String(item.id)===String(branch));return{branch,label:catalogBranch?.label||`${choice.branch?.college?.name||'College'} — ${choice.branch?.name||'Branch'}`};})||[]);setLocked(Boolean(preference?.isLocked));setSelectedBranch('');},[round,preferences,all]);
 const add=()=>{const choice=all.find(item=>String(item.id)===String(selectedBranch));if(choice&&!choices.some(item=>String(item.branch)===String(choice.id)))setChoices(current=>[...current,{branch:choice.id,label:choice.label}]);setSelectedBranch('');};
 const save=async()=>{if(!round){setErr('Select an active admission round first.');return;}if(!choices.length){setErr('Add at least one choice.');return;}try{const response=await api.put('/preferences',{admissionRound:round,choices:choices.map(choice=>({branch:choice.branch}))});setPreferences(current=>[...current.filter(item=>String(item.admissionRound?._id||item.admissionRound)!==String(round)),response.data]);setSaved('Preferences saved successfully.');setErr('');}catch(e){setErr(e.message||'Unable to save preferences.');}};
 const lock=async()=>{if(!round){setErr('Select an active admission round first.');return;}try{const response=await api.post(`/preferences/${round}/lock`);setPreferences(current=>[...current.filter(item=>String(item.admissionRound?._id||item.admissionRound)!==String(round)),response.data]);setSaved(response.message||'Preferences locked successfully.');setErr('');}catch(e){setErr(e.message||'Unable to lock preferences.');}};
 return <><Header tag="CHOICE FILLING" title="Your preferences" desc="Arrange your preferred programmes. Save first, then lock your choices before allocation."/><div className="panel"><div className="row-actions"><label>Admission round<select value={round} onChange={event=>{setRound(event.target.value);setSaved('');setErr('');}}><option value="">Select an active round</option>{rounds.map(item=><option key={item._id} value={item._id}>{item.name} · {item.status}</option>)}</select></label><button className="btn secondary" type="button" onClick={refreshRounds}>Refresh rounds</button></div><div className="inline-add"><select value={selectedBranch} disabled={locked||!round} onChange={event=>setSelectedBranch(event.target.value)}><option value="">Choose a college and branch</option>{all.map(item=><option value={item.id} key={item.id}>{item.label}</option>)}</select><button className="btn secondary" type="button" disabled={locked||!selectedBranch} onClick={add}><Plus size={15}/> Add choice</button></div><div className="choice-list">{choices.map((choice,index)=><div className="choice" key={choice.branch}><b>{index+1}</b><span>{choice.label}</span><button type="button" disabled={locked} onClick={()=>setChoices(current=>current.filter(item=>item.branch!==choice.branch))}>Remove</button></div>)}</div><div className="row-actions"><button className="btn primary" type="button" onClick={save} disabled={locked||!round}>Save preferences</button><button className="btn secondary" type="button" onClick={lock} disabled={locked||!round||!choices.length}>Lock preferences</button></div>{locked&&<div className="alert success">These preferences are locked and cannot be changed.</div>}{saved&&<div className="alert success">{saved}</div>}{err&&<div className="alert error">{err}</div>}</div></>}
export function Notifications(){
 const[data,setData]=useState([]),[draft,setDraft]=useState({title:'',message:'',audience:'all'}),[busy,setBusy]=useState(false),[busyRead,setBusyRead]=useState(''),[err,setErr]=useState(''),[message,setMessage]=useState(''),[unreadCount,setUnreadCount]=useState(0),[filter,setFilter]=useState('all');
 const{user}=useAuth();
 const load=async()=>{try{const response=await api.get('/notifications');setData(response.data||[]);setUnreadCount(response.unreadCount||0);setErr('');}catch(error){setErr(error.message||'Unable to load notifications.');}};
 useEffect(()=>{load();},[]);
 const markRead=async id=>{setErr('');setMessage('');setBusyRead(id);try{const response=await api.patch(`/notifications/${id}/read`);const updated=response.data;setData(current=>current.map(item=>item._id===id?{...item,...updated,isRead:true}:item));setUnreadCount(count=>Math.max(0,count-1));setMessage('Notification marked as read.');}catch(error){setErr(error.message||'Unable to update this notification.');}finally{setBusyRead('');}};
 const create=async event=>{event.preventDefault();setBusy(true);setErr('');setMessage('');try{await api.post('/notifications',{...draft,title:draft.title.trim(),message:draft.message.trim()});setDraft({title:'',message:'',audience:'all'});setMessage('Announcement published.');await load();}catch(error){setErr(error.message||'Unable to publish the announcement.');}finally{setBusy(false);}};
 const visible=data.filter(item=>filter==='all'||!item.isRead);
 return <><Header tag="CAMPUS UPDATES" title={user?.role==='admin'?'Announcements':'Notifications'} desc={user?.role==='admin'?'Publish clear, audience-specific updates and review delivery status.':'Read official counselling updates and keep track of what you have seen.'}/>{user?.role==='admin'&&<section className="panel announcement-composer"><div className="section-heading"><div><span className="eyebrow">ADMINISTRATOR MESSAGE</span><h2>Publish an announcement</h2></div></div><form className="form-grid" onSubmit={create}><label>Title<input maxLength="120" value={draft.title} onChange={event=>setDraft({...draft,title:event.target.value})} placeholder="Example: Document verification deadline" required/></label><label>Audience<select value={draft.audience} onChange={event=>setDraft({...draft,audience:event.target.value})}><option value="all">All users</option><option value="student">Students</option><option value="admin">Administrators</option></select></label><label className="announcement-message-field">Message<textarea maxLength="2000" value={draft.message} onChange={event=>setDraft({...draft,message:event.target.value})} rows="4" placeholder="Share the update, deadline, and any action required." required/><small>{draft.message.length}/2,000 characters</small></label><div className="form-action"><button className="btn primary" disabled={busy}>{busy?'Publishing…':'Publish announcement'}</button></div></form></section>}{message&&<div className="workflow-message success">{message}</div>}{err&&<div className="workflow-message error">{err}</div>}<div className="notifications-toolbar"><div><span className="notification-count">{unreadCount}</span><span>unread {unreadCount===1?'notification':'notifications'}</span></div><div className="row-actions"><button className={`btn tiny ${filter==='all'?'primary':'secondary'}`} type="button" onClick={()=>setFilter('all')}>All updates</button><button className={`btn tiny ${filter==='unread'?'primary':'secondary'}`} type="button" onClick={()=>setFilter('unread')}>Unread only</button><button className="btn tiny secondary" type="button" onClick={load}><RefreshCw size={14}/> Refresh</button></div></div><div className="notice-list">{visible.map(notification=><article className={`notice-card ${notification.isRead?'read':'unread'}`} key={notification._id}><div className="notice-icon"><AlertCircle size={19}/></div><div className="notice-content"><div className="notice-heading"><b>{notification.title}</b><span className={`badge ${notification.isRead?'neutral':'pending'}`}>{notification.isRead?'Read':'New'}</span></div><p>{notification.message}</p><small>{new Date(notification.createdAt).toLocaleString()}</small></div>{!notification.isRead&&<button className="btn tiny secondary-btn" type="button" disabled={busyRead===notification._id} onClick={()=>markRead(notification._id)}>{busyRead===notification._id?'Saving…':'Mark read'}</button>}</article>)}</div>{!visible.length&&<div className="empty">{filter==='unread'?'You are all caught up.':'No announcements have been published yet.'}</div>}</>}
export function StudentAllocations(){const[data,setData]=useState([]),[err,setErr]=useState(''),[msg,setMsg]=useState('');const load=async()=>{try{const r=await api.get('/allocations/mine');setData(Array.isArray(r.data)?r.data:Array.isArray(r.data?.data)?r.data.data:[]);setErr('');}catch(e){setErr(e.message||'Unable to load allocation results.');}};useEffect(()=>{load();},[]);const respond=async(id,action)=>{setErr('');setMsg('');try{const r=await api.patch(`/allocations/${id}/respond`,{action});setMsg(r.message||`Offer ${action}ed successfully.`);await load();}catch(e){setErr(e.message||'Unable to respond to this offer.');}};return <><Header tag="SEAT OUTCOMES" title="Your allocation status" desc="Track final seat offers and understand your counselling result."/>{err&&<div className="alert error">{err}</div>}{msg&&<div className="alert success">{msg}</div>}<div className="table-wrap"><table><thead><tr><th>Round</th><th>College</th><th>Branch</th><th>Rank at allocation</th><th>Status</th><th>Response</th></tr></thead><tbody>{data.map(item=><tr key={item._id}><td>{item.admissionRound?.name||'—'}</td><td>{item.branch?.college?.name||'—'}</td><td>{item.branch?.name||'—'}</td><td>{item.rankAtAllocation ?? '—'}</td><td><span className={`badge ${String(item.status||'allocated').toLowerCase()}`}>{item.status||'allocated'}</span></td><td>{item.status==='provisional'&&<div className="row-actions"><button className="btn tiny success-btn" onClick={()=>respond(item._id,'accept')}>Accept</button><button className="btn tiny danger-btn" onClick={()=>respond(item._id,'decline')}>Decline</button></div>}</td></tr>)}</tbody></table>{!data.length&&!err&&<div className="empty">No allocation has been finalized for you yet. Keep checking as the counselling process moves forward.</div>}</div></>}
export function AiAdvisor({ compact = false, onClose }) {
  const { user } = useAuth();
  const [messages, setMessages] = useState([]);
  const [draft, setDraft] = useState('');
  const [busy, setBusy] = useState(false);
  const [historyLoading, setHistoryLoading] = useState(true);
  const [err, setErr] = useState('');
  const messagesEndRef = useRef(null);
  const isAdmin = user?.role === 'admin';

  const loadHistory = async () => {
    setHistoryLoading(true);
    try {
      const response = await api.get('/ai/history');
      const history = Array.isArray(response.data)
        ? response.data
        : Array.isArray(response.data?.data) ? response.data.data : [];
      setMessages(history.map((item) => ({ id: item._id, role: item.role, text: item.message })));
      setErr('');
    } catch (error) {
      setErr(error.message || 'Unable to load adviser history.');
    } finally {
      setHistoryLoading(false);
    }
  };

  useEffect(() => { loadHistory(); }, []);
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth', block: 'end' });
  }, [messages, busy]);

  const send = async (event) => {
    event.preventDefault();
    const message = draft.trim();
    if (!message || busy) return;
    setMessages((previous) => [...previous, { id: `user-${Date.now()}`, role: 'user', text: message }]);
    setDraft('');
    setBusy(true);
    setErr('');
    try {
      const response = await api.post('/ai/chat', { message });
      const answer = response.answer || response.data?.answer;
      if (typeof answer !== 'string' || !answer.trim()) {
        throw new Error('The AI service returned an empty answer.');
      }
      setMessages((previous) => [...previous, {
        id: `assistant-${Date.now()}`,
        role: 'assistant',
        text: answer
      }]);
    } catch (error) {
      setErr(error.message || 'Unable to reach the AI adviser.');
    } finally {
      setBusy(false);
    }
  };

  const prompts = isAdmin
    ? ['How many documents are awaiting review?', 'Summarize the latest historical cutoffs.', 'Which rounds have locked preferences?']
    : ['Explain what my rank suggests using site cutoffs.', 'How should I order my college preferences?', 'What documents are required for counselling?'];
  const content = (
    <section className={`panel advisor-panel ${isAdmin ? 'admin-advisor' : ''} ${compact ? 'advisor-compact' : ''}`}>
      <div className="advisor-heading">
        <div>
          <span className="advisor-status"><span className="status-dot" /> AI ADVISER</span>
          <h2>{isAdmin ? 'Operations and counselling assistant' : 'Your admission guidance assistant'}</h2>
          <p>{isAdmin
            ? 'Answers use current platform records for operational questions.'
            : 'Get clear explanations of admission options and your counselling data.'}</p>
        </div>
        {compact
          ? <button className="advisor-close" type="button" onClick={onClose} aria-label="Close AI adviser"><X size={19} /></button>
          : <span className="advisor-scope">{isAdmin ? 'ADMIN WORKSPACE' : 'STUDENT WORKSPACE'}</span>}
      </div>
      <div className="chat-box" role="log" aria-label="Conversation with the Rank2Campus adviser" aria-live="polite" aria-relevant="additions text">
        {historyLoading
          ? <div className="empty">Loading your conversation…</div>
          : messages.length
            ? messages.map((message) => (
              <article key={message.id} className={`chat-bubble ${message.role}`}>
                <b>{message.role === 'user' ? 'You' : 'Rank2Campus AI'}</b>
                <p>{message.text}</p>
              </article>
            ))
            : <div className="advisor-empty">
              <span className="advisor-empty-icon"><CheckCircle2 size={22} /></span>
              <b>What can I help you with?</b>
              <p>Ask a general question or ask about information available in Rank2Campus.</p>
            </div>}
        {busy && <div className="chat-bubble assistant typing-indicator"><b>Rank2Campus AI</b><p>Reviewing your question and relevant data…</p></div>}
        <div ref={messagesEndRef} />
      </div>
      {!messages.length && !historyLoading && (
        <div className="advisor-prompts">
          {prompts.map((prompt) => (
            <button type="button" className="advisor-prompt" key={prompt} onClick={() => setDraft(prompt)}>{prompt}</button>
          ))}
        </div>
      )}
      <form className="chat-form" onSubmit={send}>
        <label className="sr-only" htmlFor="advisor-question">Your question</label>
        <textarea
          id="advisor-question"
          maxLength="3000"
          rows="3"
          value={draft}
          onChange={(event) => setDraft(event.target.value)}
          placeholder={isAdmin
            ? 'Ask about a student workflow, counselling, historical cutoffs, or a general topic…'
            : 'Ask about counselling, your profile, historical cutoffs, or a general topic…'}
          required
        />
        <div className="chat-form-footer">
          <small>{draft.length}/3,000 · Cutoff answers are estimates, not admission guarantees.</small>
          <button className="btn primary" disabled={busy || historyLoading || !draft.trim()}>
            {busy ? 'Thinking…' : <>Ask adviser <Send size={15} /></>}
          </button>
        </div>
      </form>
      {err && <div className="workflow-message error">{err}</div>}
    </section>
  );
  return compact
    ? <div className="advisor-widget-content">{content}</div>
    : <><Header tag={isAdmin ? 'ADMIN DATA ASSISTANT' : 'AI COUNSELLOR'} title={isAdmin ? 'Admission data & counselling' : 'Smart admission guidance'} desc={isAdmin
      ? 'Ask general questions or get answers grounded in current student, round, document and cutoff data.'
      : 'Ask general questions or get admission guidance grounded in your profile and platform cutoff history.'} />{content}</>;
}
export function AdminStudents(){const[data,setData]=useState([]),[err,setErr]=useState('');useEffect(()=>{api.get('/admin/students').then(r=>setData(r.data||[])).catch(e=>setErr(e.message||'Unable to load students.'));},[]);return <><Header tag="ROOT CONTROL CENTER" title="Student directory" desc="Open a student record to review the complete profile, documents, preferences, and allocation history."/>{err&&<div className="alert error">{err}</div>}<div className="table-wrap"><table><thead><tr><th>Student</th><th>Email</th><th>Application no.</th><th>Exam</th><th>Rank</th><th>Category</th></tr></thead><tbody>{data.map(student=><tr key={student._id}><td><Link className="student-link" to={`/admin/students/${student._id}`}>{student.fullName||student.user?.name||'View student'}</Link></td><td>{student.user?.email||'—'}</td><td>{student.applicationNumber||'—'}</td><td>{student.examName||'—'}</td><td>{student.rank??'Not set'}</td><td>{student.category||'—'}</td></tr>)}</tbody></table>{!data.length&&!err&&<div className="empty">No students registered yet.</div>}</div></>}
