 const remove=async round=>{if(round.allocationCount>0){setErr('This round has allocation history and cannot be deleted.');return;}const preferenceCount=round.preferenceCount||0;const prompt=preferenceCount?`Delete ${round.name}? This will also permanently delete ${preferenceCount} saved preference set(s). Allocation records are never deleted.`:`Delete ${round.name}? Allocation records are never deleted.`;if(!window.confirm(prompt))return;setMsg('');setErr('');try{const response=await api.delete(`/admin/rounds/${round._id}`);await load();setMsg(response.message||'Admission round removed successfully.');}catch(error){setErr(error.message||'Unable to delete round.');}};
 const resetCycle=async()=>{if(cycleBusy||!window.confirm('This will permanently remove all current student records, documents, preferences, notifications, allocations, and admission rounds for the current cycle. Colleges, branches, and historical cutoffs will remain. Proceed?'))return;setCycleBusy(true);setMsg('');setErr('');try{const response=await api.post('/admin/reset-cycle');setMsg(response.message||'Admission cycle reset successfully.');await load();}catch(error){setErr(error.message||'Unable to reset the cycle.');}finally{setCycleBusy(false);}};
